sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // Get checker submitted time from bulk record
    try {
        var checkerSubmittedTime = current.checker_submitted_time; // Should be a GlideDateTime

        var handlerTaskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        handlerTaskGR.addQuery('trade_task_type', 'GHSS Handler');
        handlerTaskGR.addQuery('state', '4');
        handlerTaskGR.addQuery('bulk_id', current.sys_id);
        if (checkerSubmittedTime) {
            handlerTaskGR.addQuery('sys_created_on', '>=', checkerSubmittedTime); // Only after checker submits
        }
        handlerTaskGR.query();

        var rejectedCount = 0;
        while (handlerTaskGR.next()) {
            rejectedCount++;
        }

        // Update active trade count in bulk
        current.active_trade_count = rejectedCount;
        current.update();
    } catch (e) {
        gs.info('Error in updating active trade count BR: ' + e.message);
    }
})(current, previous);
